//! Runtime helpers referenced by code generated by `caplet-macros`.
//!
//! This crate exists so the generated code can call stable runtime
//! entry points (`kernel_init`, `kernel_start`, `spawn_main`,
//! `Spawner`, `TaskDescriptor`, `TaskHandle`) without the macro
//! output depending on the heavy kernel types directly.

#![no_std]
extern crate alloc;

use alloc::sync::Arc;
use caplet_async::{Executor, Spawner as InnerSpawner};
use caplet_sync::SpinLock;
use core::sync::atomic::{AtomicBool, Ordering};

/// Re-export of the async Spawner so macro-generated code can reference
/// it as `::caplet_macros_exports::Spawner`.
pub type Spawner = InnerSpawner;

/// Static flag tracking whether the kernel has been initialised.
static INITIALIZED: AtomicBool = AtomicBool::new(false);

/// Initialize the global kernel. Safe to call multiple times.
pub fn kernel_init() {
    if INITIALIZED.swap(true, Ordering::SeqCst) {
        return;
    }
    let config = caplet_kernel::KernelConfig::qemu();
    unsafe { caplet_kernel::kernel::init_kernel(config) };
    // Install the platform idle hook (WFI on Cortex-M, no-op on host).
    // The `caplet_cortex_m` port is the one that exposes the real
    // implementation; if it is not linked the weak symbol in the
    // kernel crate is used and the kernel busy-spins in the idle task.
    #[cfg(target_arch = "arm")]
    caplet_cortex_m::tickless::install();
}

/// Start the kernel scheduler. Never returns.
pub fn kernel_start() -> ! {
    let kernel = unsafe { caplet_kernel::kernel::get_kernel() };
    match kernel {
        Some(k) => k.start(),
        None => loop {
            core::hint::spin_loop();
        },
    }
}

/// Cell holding the executor that the `#[main]` macro's boot task
/// lives in.
struct ExecutorCell {
    inner: SpinLock<Option<Arc<Executor>>>,
}

impl ExecutorCell {
    const fn new() -> Self {
        Self { inner: SpinLock::new(None) }
    }
    fn replace(&self, v: Option<Arc<Executor>>) -> Option<Arc<Executor>> {
        let mut g = self.inner.lock();
        let old = (*g).take();
        *g = v;
        old
    }
    fn get(&self) -> Option<Arc<Executor>> {
        self.inner.lock().clone()
    }
}

static SPAWNED_EXECUTOR: ExecutorCell = ExecutorCell::new();

/// Spawn the user's `main` as the boot task. `main` is the user's
/// `fn main()` that the `#[caplet::main]` macro re-exported.
pub fn spawn_main(main: fn() -> !) {
    let executor = Arc::new(Executor::new());
    let spawner = InnerSpawner::new(Arc::clone(&executor));
    spawner.spawn_with(
        async move {
            main();
        },
        0,
        4096,
    );
    SPAWNED_EXECUTOR.replace(Some(executor));
}

/// Drain the spawned executor's task queue. Called by the scheduler
/// loop.
pub fn drive_executor() {
    if let Some(exec) = SPAWNED_EXECUTOR.get() {
        exec.run_until_idle();
    }
}

/// Spawn an async function on the boot executor at the given priority.
/// Used by board crates that want to spawn from `main()` directly
/// instead of relying on the `#[task]` macro.
pub fn spawn_with_priority<F>(future: F, priority: u8)
where
    F: core::future::Future<Output = ()> + Send + 'static,
{
    if let Some(exec) = SPAWNED_EXECUTOR.get() {
        exec.spawn_with_priority(future, priority);
    } else {
        // Lazy init if user did not call `spawn_main` first.
        let executor = Arc::new(Executor::new());
        SPAWNED_EXECUTOR.replace(Some(Arc::clone(&executor)));
        executor.spawn_with_priority(future, priority);
    }
}

/// Drive the boot executor forever. Used as the final statement of
/// `fn main()` in board crates.
pub fn drive_executor_forever() -> ! {
    loop {
        drive_executor();
        // Yield to any interrupt or WFI when idle.
        caplet_sync::cpu_relax();
    }
}

/// Description of a task for kernel introspection.
#[derive(Debug, Clone, Copy)]
pub struct TaskDescriptor {
    /// Task name
    pub name: &'static str,
    /// Priority (0..=31)
    pub priority: u8,
    /// Stack size in bytes
    pub stack: usize,
    /// Optional spawn pool
    pub pool: Option<&'static str>,
}

/// Handle to a spawned task — re-exported from `caplet_async` so
/// macro-generated code can reference `::caplet_macros_exports::TaskHandle`.
pub use caplet_async::TaskHandle as TaskHandle;